def powersetSums (A : Finset Nat) : Finset Nat := (A.powerset.attach.image (fun S => S.1.sum id))
def sumDistinct (A : Finset Nat) : Bool := (powersetSums A).card == 2 ^ A.card
def checkWitness : Bool := sumDistinct {1, 2, 4} && sumDistinct {2, 3, 4}

